/**
 * Lightweight Prism-compatible Syntax Highlighter
 * Supports: Java, Dart, JavaScript, TypeScript, CSS, HTML, SQL, Dockerfile, YAML, Bash, Python, JSON
 * Works 100% offline & file:// protocol with zero dependencies.
 */
(function () {
  'use strict';

  var Prism = window.Prism || {};
  window.Prism = Prism;

  Prism.languages = Prism.languages || {};

  function escapeHtml(str) {
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  var COMMON_KEYWORDS = 'abstract|as|assert|async|await|break|case|catch|class|const|continue|debugger|default|delete|do|else|enum|export|extends|false|final|finally|for|from|function|get|if|implements|import|in|instanceof|interface|is|let|new|null|of|package|private|protected|public|return|set|static|super|switch|this|throw|true|try|typeof|var|void|while|with|yield|int|float|double|boolean|char|byte|short|long|String|List|Map|Set|Future|Stream|dynamic|var';
  var SQL_KEYWORDS = 'select|from|where|insert|into|update|delete|create|table|drop|alter|add|index|primary|key|foreign|references|join|inner|left|right|full|outer|cross|on|group|by|order|having|limit|offset|union|all|distinct|as|between|like|in|is|null|and|or|not|exists|case|when|then|else|end|asc|desc|values|set|count|sum|avg|min|max';
  var DOCKER_KEYWORDS = 'from|as|run|cmd|label|maintainer|expose|env|add|copy|entrypoint|volume|user|workdir|arg|onbuild|stopsignal|healthcheck|shell';
  var YAML_KEYWORDS = 'true|false|yes|no|on|off|null';
  var BASH_KEYWORDS = 'if|then|else|elif|fi|for|while|until|in|do|done|case|esac|function|return|exit|sudo|docker|run|build|git|npm|npx|yarn|pnpm|curl|wget|chmod|chown|mkdir|cd|ls|cat|echo|touch|grep|sed|awk|export|source';
  var PYTHON_KEYWORDS = 'def|class|import|from|as|return|if|elif|else|while|for|in|try|except|finally|with|lambda|yield|raise|pass|break|continue|global|nonlocal|assert|async|await|True|False|None|and|or|not|is';

  function tokenize(code, lang) {
    if (!code) return '';

    var tokens = [];
    function mask(str, cls) {
      var id = '___PRISM_' + tokens.length + '___';
      tokens.push('<span class="token ' + cls + '">' + escapeHtml(str) + '</span>');
      return id;
    }

    var safe = code;

    // 1. Strings (single, double, template backticks)
    safe = safe.replace(/(".*?(?<!\\)"|'.*?(?<!\\)'|`[\s\S]*?(?<!\\)`)/g, function (m) {
      return mask(m, 'string');
    });

    // 2. Comments
    // Multi-line /* ... */
    safe = safe.replace(/\/\*[\s\S]*?\*\//g, function (m) {
      return mask(m, 'comment');
    });
    // Single line // or #
    safe = safe.replace(/(?:\/\/|#).*$/gm, function (m) {
      return mask(m, 'comment');
    });
    // SQL comments --
    if (lang === 'sql') {
      safe = safe.replace(/--.*$/gm, function (m) {
        return mask(m, 'comment');
      });
    }

    // 3. Numbers
    safe = safe.replace(/\b\d+(?:\.\d+)?\b/g, function (m) {
      return mask(m, 'number');
    });

    // 4. Keywords
    var kwPattern = COMMON_KEYWORDS;
    if (lang === 'sql') kwPattern = SQL_KEYWORDS;
    else if (lang === 'docker' || lang === 'dockerfile') kwPattern = DOCKER_KEYWORDS;
    else if (lang === 'yaml' || lang === 'yml') kwPattern = YAML_KEYWORDS;
    else if (lang === 'bash' || lang === 'sh' || lang === 'shell') kwPattern = BASH_KEYWORDS;
    else if (lang === 'python' || lang === 'py') kwPattern = PYTHON_KEYWORDS;

    safe = safe.replace(new RegExp('\\b(' + kwPattern + ')\\b', 'gi'), function (m) {
      return mask(m, 'keyword');
    });

    // 5. Annotations / Decorators (@Override, @Component, etc.)
    safe = safe.replace(/@\w+/g, function (m) {
      return mask(m, 'atrule');
    });

    // 6. Functions (name followed by '(')
    safe = safe.replace(/\b([a-zA-Z_$][a-zA-Z0-9_$]*)(?=\s*\()/g, function (m) {
      return mask(m, 'function');
    });

    // 7. Punctuation
    safe = safe.replace(/[{}\[\]();:,.<>!=+*\/%&|^~?-]/g, function (m) {
      return mask(m, 'punctuation');
    });

    // 8. Escape the rest of raw code
    safe = escapeHtml(safe);

    // 9. Unmask all tokens in reverse
    for (var i = tokens.length - 1; i >= 0; i--) {
      safe = safe.replace('___PRISM_' + i + '___', tokens[i]);
    }

    return safe;
  }

  Prism.highlightElement = function (element) {
    if (!element) return;
    var langClass = (element.className || '').match(/language-([a-z0-9_-]+)/i);
    var lang = langClass ? langClass[1].toLowerCase() : 'text';
    var rawText = element.textContent || '';
    element.innerHTML = tokenize(rawText, lang);
  };

  Prism.highlightAllUnder = function (container) {
    if (!container) return;
    var codeElements = container.querySelectorAll('code[class*="language-"], pre code');
    for (var i = 0; i < codeElements.length; i++) {
      Prism.highlightElement(codeElements[i]);
    }
  };

  Prism.highlightAll = function () {
    Prism.highlightAllUnder(document);
  };
})();
